import{_ as p,a0 as t,w as r,s as n,ao as l,I as i,x as s,a1 as d,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"Linux 系统下查看硬件信息命令大全 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 系统下查看硬件信息命令大全 | LCTT (201601) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 系统下查看硬件信息命令大全 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 系统下查看硬件信息命令大全 | LCTT (201601) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201601/20160104 How to Check Hardware Information on Linux Using Command Line","title":"Linux 系统下查看硬件信息命令大全","tag":"201601","desc":""},"relativePath":"201601/20160104 How to Check Hardware Information on Linux Using Command Line.md","filePath":"[post].md"}'),c={name:"201601/20160104 How to Check Hardware Information on Linux Using Command Line.md"};function h(m,e,f,u,_,w){const a=t("Link");return r(),n("div",null,[e[13]||(e[13]=l(`<h1 id="linux-系统下查看硬件信息命令大全" tabindex="-1">Linux 系统下查看硬件信息命令大全 <a class="header-anchor" href="#linux-系统下查看硬件信息命令大全" aria-label="Permalink to “Linux 系统下查看硬件信息命令大全”">​</a></h1><p><img src="https://maketecheasier-holisticmedia.netdna-ssl.com/assets/uploads/2015/12/hdd_info_featured-1.png" alt=""></p><p>有许多命令可以用来查看 Linux 系统上的硬件信息。有些命令只能够打印出像 CPU 和内存这一特定的硬件组件信息，另外一些命令可以查看多种硬件组件的信息。</p><p>这个教程可以带大家快速了解一下查看各种硬件设备的信息和配置详情的最常用的命令。</p><h3 id="lscpu" tabindex="-1">lscpu <a class="header-anchor" href="#lscpu" aria-label="Permalink to “lscpu”">​</a></h3><p><code>lscpu</code>命令能够查看 CPU 和处理单元的信息。该命令没有任何其他选项或者别的功能。</p><pre><code>lscpu
</code></pre><p>运行该命令会看到下面输出：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_lscpu.png" alt="hdd_info_lscpu"></p><h3 id="lspci" tabindex="-1">lspci <a class="header-anchor" href="#lspci" aria-label="Permalink to “lspci”">​</a></h3><p><code>lspci</code>是另一个命令行工具，可以用来列出所有的 PCI 总线，还有与 PCI 总线相连的设备的详细信息，比如 VGA 适配器、显卡、网络适配器、usb 端口、SATA 控制器等。</p><pre><code>lspci
</code></pre><p>你可以看到类似下图的输出信息。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_lspci-1.png" alt="hdd_info_lspci"></p><p>可以通过运行下面的命令来过滤出特定设备的信息：</p><pre><code>lspci -v | grep &quot;VGA&quot; -A 12
</code></pre><p>运行上面的命令可以看到类似下图的关于显卡的信息。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_lspci_vga.png" alt="hdd_info_lspci_vga"></p><h3 id="lshw" tabindex="-1">lshw <a class="header-anchor" href="#lshw" aria-label="Permalink to “lshw”">​</a></h3><p><code>lshw</code>是一个通用的工具，可以列出多种硬件单元的详细或者概要的信息，比如 CPU、内存、usb 控制器、硬盘等。<code>lshw</code>能够从各个“/proc”文件中提取出相关的信息。</p><pre><code>lshw -short
</code></pre><p>通过运行上面的命令可以看到下面的信息。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_lshw.png" alt="hdd_info_lshw"></p><h3 id="lsscsi" tabindex="-1">lsscsi <a class="header-anchor" href="#lsscsi" aria-label="Permalink to “lsscsi”">​</a></h3><p>通过运行下面的命令可以列出像硬盘和光驱等 scsi/sata 设备的信息：</p><pre><code>lsscsi
</code></pre><p>会得到类似下面的输出。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_lsscsi-1.png" alt="hdd_info_lsscsi"></p><h3 id="lsusb" tabindex="-1">lsusb <a class="header-anchor" href="#lsusb" aria-label="Permalink to “lsusb”">​</a></h3><p><code>lsusb</code>命令能够列出 USB 控制器和与 USB 控制器相连的设备的详细信息。默认情况下，<code>lsusb</code>命令只打印出概要信息。可以通过使用-v参数打印每一个usb端口的详细信息。</p><pre><code>lsusb
</code></pre><p>可以看到下面输出。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_lsusb.png" alt="hdd_info_lsusb"></p><h3 id="inxi" tabindex="-1">Inxi <a class="header-anchor" href="#inxi" aria-label="Permalink to “Inxi”">​</a></h3><p><code>Inxi</code>是一个 bash 脚本，能够从系统的多个来源和命令获取硬件信息，并打印出一个非技术人员也能看懂的友好的报告。</p><p>默认情况下，Ubuntu 上没有安装<code>inxi</code>。可以通过运行下面命令来安装<code>Inxi</code>：</p><pre><code>sudo apt-get install inxi
</code></pre><p>安装完<code>Inxi</code>之后，通过运行下面命令能够得到硬件相关的信息：</p><pre><code>inxi -Fx
</code></pre><p>能够得到类似下图的输出。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_inxi.jpg" alt="hdd_info_inxi"></p><h3 id="df" tabindex="-1">df <a class="header-anchor" href="#df" aria-label="Permalink to “df”">​</a></h3><p><code>df</code>命令能够列出不同分区的概要信息、挂载点、已用的和可用的空间。</p><p>可以在使用<code>df</code>命令的时候加上<code>-H</code>参数。</p><pre><code>df -H
</code></pre><p>会得到下面的输出。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_df-1.png" alt="hdd_info_df"></p><h3 id="free" tabindex="-1">Free <a class="header-anchor" href="#free" aria-label="Permalink to “Free”">​</a></h3><p>通过使用<code>free</code>命令可以查看系统中使用的、闲置的和 RAM 的总体数量。</p><pre><code>free -m
</code></pre><p>会看到下面输出。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_free.png" alt="hdd_info_free"></p><h3 id="dmidecode" tabindex="-1">Dmidecode <a class="header-anchor" href="#dmidecode" aria-label="Permalink to “Dmidecode”">​</a></h3><p><code>dmidecode</code>命令与其他命令不同。该命令是从硬件中的 DMI 表中读取信息的。</p><p>要查看处理器的信息，运行下面命令：</p><pre><code>sudo dmidecode -t processor
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_dmi_processor.jpg" alt="hdd_info_dmi_processor"></p><p>要查看内存的信息，运行下面命令：</p><pre><code>sudo dmidecode -t memory
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_dmi_memory.png" alt="hdd_info_dmi_memory"></p><p>要查看 bios 的信息，运行下面命令：</p><pre><code>sudo dmidecode -t bios
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_dmi_bios.png" alt="hdd_info_dmi_bios"></p><h3 id="hdparm" tabindex="-1">Hdparm <a class="header-anchor" href="#hdparm" aria-label="Permalink to “Hdparm”">​</a></h3><p><code>hdparm</code>命令可以用来显示像硬盘这样的 sata 设备的信息。</p><pre><code>sudo hdparm
</code></pre><p>可以看到下面的输出。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_hdparm.png" alt="hdd_info_hdparm"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>每个命令都有不同的方式来获取硬件的信息。在查看特定的硬件信息的时候，可以尝试使用不同的方式。上面所有的命令行工具在大部分的 Linux 发行版本中都是可以使用的，可以很容易的从仓库中获取安装。</p><hr>`,71)),i("p",null,[e[1]||(e[1]=s("via: ",-1)),d(a,{href:"https://www.maketecheasier.com/check-hardware-information-linux/"},{default:o(()=>[...e[0]||(e[0]=[s("https://www.maketecheasier.com/check-hardware-information-linux/",-1)])]),_:1})]),i("p",null,[e[5]||(e[5]=s("作者：",-1)),d(a,{href:"https://www.maketecheasier.com/author/hiteshjethva/"},{default:o(()=>[...e[2]||(e[2]=[s("Hitesh Jethva",-1)])]),_:1}),e[6]||(e[6]=s(" 译者：",-1)),d(a,{href:"https://github.com/sonofelice"},{default:o(()=>[...e[3]||(e[3]=[s("sonofelice",-1)])]),_:1}),e[7]||(e[7]=s(" 校对：",-1)),d(a,{href:"https://github.com/wxy"},{default:o(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1})]),i("p",null,[e[10]||(e[10]=s("本文由 ",-1)),d(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[8]||(e[8]=[s("LCTT",-1)])]),_:1}),e[11]||(e[11]=s(" 原创编译，",-1)),d(a,{href:"https://linux.cn/"},{default:o(()=>[...e[9]||(e[9]=[s("Linux中国",-1)])]),_:1}),e[12]||(e[12]=s(" 荣誉推出",-1))])])}const k=p(c,[["render",h]]);export{g as __pageData,k as default};
